import React from 'react';
import styled from 'styled-components';

import { ANNOTATIONS_PADDING_BOTTOM } from './constants.js';
import { AnnotationsChartProps } from '../../../annotations/types/annotations-chart-props.js';
import { AnnotationsTimeseriesRenderer } from '../../../core/components/annotations-timeseries/AnnotationsTimeseriesRenderer.js';
import { SelectionState as AnnotationsTimeseriesSelectionState } from '../../../core/components/annotations-timeseries/types/state.js';
import { ChartGrid } from '../../../core/components/chart-grid/ChartGridRoot.js';
import { useGridPlotSize } from '../../../core/components/chart-grid/hooks/useGridPlotSize.js';
import { useSetState } from '../../hooks/store/selectors.js';
import { useAnnotationsConfig } from '../../hooks/useAnnotationsConfig.js';
import { useXScales } from '../../hooks/useXScale.js';
import { AREAS } from '../../types/timeseries-grid-area-rules.js';
import { filterAnnotationsOutOfBounds } from '../../utils/filter-annotations-out-of-bounds.js';

const StyledGridArea = /* @__PURE__ */ styled(ChartGrid.GridArea)`
  padding-bottom: ${ANNOTATIONS_PADDING_BOTTOM}px;
`;

export const TimeseriesChartAnnotationsArea = ({
  showLabels,
  annotationsActions,
}: AnnotationsChartProps) => {
  const annotation = useAnnotationsConfig()!;
  const setState = useSetState();
  const { currentScale: xScale } = useXScales();
  const { width } = useGridPlotSize();

  const handleUpdateIndicators = (
    event: Partial<AnnotationsTimeseriesSelectionState>,
  ) => {
    setState((prev) => ({
      ...prev,
      annotations: {
        ...prev.annotations,
        selection: { ...prev.annotations?.selection, ...event },
      },
    }));
  };

  const tracks = filterAnnotationsOutOfBounds(
    annotation.tracks,
    xScale.domain(),
  );

  return (
    <StyledGridArea gridArea={AREAS.annotations}>
      {({ availableWidth, availableHeight }) => {
        const labelOffset = availableWidth - width;

        return (
          <AnnotationsTimeseriesRenderer
            tracks={tracks}
            width={availableWidth}
            height={availableHeight}
            scale={xScale}
            showLabels={showLabels}
            labelsOffset={labelOffset}
            annotationsActions={annotationsActions}
            markerGroupHover={handleUpdateIndicators}
          />
        );
      }}
    </StyledGridArea>
  );
};
